const EventStories={"cofre":{"pt-BR":{"title":"Cofre amaldiçoado","story":"Entre as raízes de uma capela abandonada, um cofre pulsa com uma luz violeta. A fechadura se abre ao seu toque, mas as sombras nas paredes parecem escolher quem ficará para trás.","opportunity":"55% de receber uma relíquia.","risk":"45% de perder uma carta aleatória do baralho.","cost":"","action":"Abrir o cofre"},"en":{"title":"Cursed Chest","story":"Among the roots of an abandoned chapel, a chest pulses with violet light. Its lock opens at your touch, but the shadows on the walls seem to be choosing who will stay behind.","opportunity":"55% chance to receive a relic.","risk":"45% chance to lose a random card from your deck.","cost":"","action":"Open the chest"}},"resgate":{"pt-BR":{"title":"Viajante aprisionado","story":"Um viajante pede ajuda de dentro de uma jaula quebrada. Ele promete apresentar companheiros dispostos a seguir sua jornada, mas o silêncio da mata sugere que os carcereiros ainda estão por perto.","opportunity":"70% de escolher um recruta entre três opções.","risk":"30% de perder uma carta aleatória durante o resgate.","cost":"","action":"Tentar o resgate"},"en":{"title":"Imprisoned Traveler","story":"A traveler calls for help from a broken cage. They promise to introduce companions willing to join your journey, but the silent forest suggests their captors are still nearby.","opportunity":"70% chance to choose a recruit from three options.","risk":"30% chance to lose a random card during the rescue.","cost":"","action":"Attempt the rescue"}},"altar":{"pt-BR":{"title":"Altar da renovação","story":"A espada sobre o altar se desfaz em pequenas luzes, e duas chamas despertam entre as ruínas. Uma inscrição avisa: para fortalecer os que continuam, alguém precisa encerrar sua jornada aqui.","opportunity":"Melhorar duas outras cartas distintas em um nível cada.","risk":"O sacrifício é definitivo e acontece antes dos upgrades.","cost":"Sacrificar uma carta escolhida do baralho.","action":"Fazer a oferenda"},"en":{"title":"Altar of Renewal","story":"The sword upon the altar dissolves into sparks, and two flames awaken among the ruins. An inscription warns: to strengthen those who continue, someone must end their journey here.","opportunity":"Upgrade two other separate cards by one level each.","risk":"The sacrifice is permanent and takes place before the upgrades.","cost":"Sacrifice one card of your choice from the deck.","action":"Make the offering"}},"caravana":{"pt-BR":{"title":"Caravana desaparecida","story":"As rodas de uma caravana desapareceram sob a lama, mas ainda há ouro espalhado entre os caixotes. Enquanto o grupo vasculha os destroços, pegadas recentes revelam que vocês talvez não sejam os primeiros a chegar.","opportunity":"60% de ganhar 18 de ouro.","risk":"40% de perder 10 de ouro.","cost":"","action":"Vasculhar os destroços"},"en":{"title":"Missing Caravan","story":"A caravan's wheels have sunk into the mud, but gold still glitters between its crates. As the party searches the wreckage, fresh footprints reveal you may not be the first to arrive.","opportunity":"60% chance to gain 18 gold.","risk":"40% chance to lose 10 gold.","cost":"","action":"Search the wreckage"}},"mercador":{"pt-BR":{"title":"Mercador encapuzado","story":"Na encruzilhada, um mercador encapuzado oferece um embrulho que se move sozinho. Ele garante que o conteúdo ajudará a expedição — embora não diga se carrega um objeto antigo ou um contrato com um novo companheiro.","opportunity":"60% de receber uma relíquia; 40% de receber um recruta aleatório.","risk":"O pagamento é feito antes de descobrir o conteúdo; nenhum resultado fica sem recompensa.","cost":"Pagar 12 de ouro.","action":"Comprar o embrulho"},"en":{"title":"Hooded Merchant","story":"At a crossroads, a hooded merchant offers a parcel that moves by itself. They insist its contents will help your expedition, but refuse to say whether it holds an ancient object or a contract with a new companion.","opportunity":"60% chance to receive a relic; 40% chance to receive a random recruit.","risk":"Payment is taken before the contents are revealed. Both outcomes grant a reward.","cost":"Pay 12 gold.","action":"Buy the parcel"}},"dojo":{"pt-BR":{"title":"Treinamento proibido","story":"Um círculo de treino ainda brilha no pátio de um dojo abandonado. Quem entrar poderá aprender uma técnica esquecida, mas as armas partidas ao redor contam o destino de quem tentou avançar cedo demais.","opportunity":"75% de melhorar a carta escolhida em um nível.","risk":"25% de perder a carta escolhida.","cost":"Escolher uma carta e pagar 10 de ouro.","action":"Iniciar o treinamento"},"en":{"title":"Forbidden Training","story":"A training circle still glows in an abandoned dojo. Whoever enters may learn a forgotten technique, but the broken weapons around it tell the fate of those who advanced too soon.","opportunity":"75% chance to upgrade the chosen card by one level.","risk":"25% chance to lose the chosen card.","cost":"Choose a card and pay 10 gold.","action":"Begin training"}},"santuario":{"pt-BR":{"title":"Santuário dos viajantes","story":"Dois viajantes se aquecem sob as lanternas do santuário e perguntam se há lugar na expedição. A guardiã aceita apresentá-los, desde que vocês deixem uma relíquia para proteger os próximos peregrinos.","opportunity":"Recrutar dois personagens entre as ofertas apresentadas antes da troca.","risk":"A relíquia entregue deixa a expedição.","cost":"Entregar uma relíquia escolhida.","action":"Acolher os viajantes"},"en":{"title":"Travelers' Sanctuary","story":"Two travelers warm themselves beneath the sanctuary lanterns and ask to join your expedition. The keeper will introduce them if you leave a relic to protect future pilgrims.","opportunity":"Recruit two characters from the offers shown before the trade.","risk":"The relic you offer leaves the expedition.","cost":"Give up one relic of your choice.","action":"Welcome the travelers"}},"forja":{"pt-BR":{"title":"Forja instável","story":"Uma forja esquecida volta a arder quando uma relíquia se aproxima da bigorna. O metal pode assumir uma nova forma, mas a chama azul oscila como se estivesse prestes a consumir tudo.","opportunity":"70% de receber outra relíquia diferente.","risk":"30% de perder a relíquia entregue sem receber outra.","cost":"Entregar uma relíquia escolhida.","action":"Arriscar a transformação"},"en":{"title":"Unstable Forge","story":"An ancient forge flares to life as a relic approaches its anvil. The metal may take on a new form, but the blue flame flickers as though it might consume everything.","opportunity":"70% chance to receive a different relic.","risk":"30% chance to lose the offered relic with no replacement.","cost":"Give up one relic of your choice.","action":"Risk the transformation"}},"mestre":{"pt-BR":{"title":"Desafio do mestre","story":"Um velho mestre bloqueia os degraus do templo com seu bastão. Ele oferece conhecimento e algumas moedas a quem superar sua prova; quem falhar terá de abandonar a expedição e permanecer como aprendiz.","opportunity":"65% de melhorar a carta escolhida em um nível e ganhar 8 de ouro.","risk":"35% de perder a carta escolhida.","cost":"Escolher uma carta para enfrentar a prova.","action":"Aceitar a prova"},"en":{"title":"Master's Challenge","story":"An old master blocks the temple steps with his staff. He offers knowledge and a few coins to anyone who passes his test. Those who fail must leave the expedition and remain as apprentices.","opportunity":"65% chance to upgrade the chosen card by one level and gain 8 gold.","risk":"35% chance to lose the chosen card.","cost":"Choose one card to take the test.","action":"Accept the challenge"}},"aposta":{"pt-BR":{"title":"Mesa de apostas","story":"Uma mesa no fundo da estalagem silencia quando o grupo se aproxima. O apostador empurra os dados e um punhado de moedas para o centro: uma única jogada decide quem paga a próxima viagem.","opportunity":"55% de receber 30 de ouro após apostar: lucro líquido de 18.","risk":"45% de perder os 12 de ouro apostados.","cost":"Apostar 12 de ouro.","action":"Lançar os dados"},"en":{"title":"Gambling Table","story":"A table at the back of the inn falls silent as your party approaches. The gambler slides dice and coins into the center: one roll will decide who pays for the next journey.","opportunity":"55% chance to receive 30 gold after betting: a net profit of 18.","risk":"45% chance to lose the 12 gold you wagered.","cost":"Bet 12 gold.","action":"Roll the dice"}},"contrabando":{"pt-BR":{"title":"Contrabandista","story":"Entre os caixotes do cais, um contrabandista apresenta um combatente que procura uma saída da cidade. A fuga parece simples, até que a luz de uma patrulha começa a varrer a água.","opportunity":"70% de escolher um recruta com upgrade 1.","risk":"30% de perder uma relíquia aleatória durante a fuga.","cost":"","action":"Organizar a fuga"},"en":{"title":"Smuggler","story":"Among the dockside crates, a smuggler introduces a fighter seeking a way out of the city. The escape seems easy until a patrol lantern begins sweeping across the water.","opportunity":"70% chance to choose a recruit with upgrade 1.","risk":"30% chance to lose a random relic during the escape.","cost":"","action":"Arrange the escape"}},"despedida":{"pt-BR":{"title":"Contrato de despedida","story":"Na bifurcação, um companheiro recebe uma proposta para escoltar mercadores por outro caminho. A separação será amigável, e os contratantes oferecem uma compensação para que a expedição siga em frente.","opportunity":"Receber 20 de ouro garantidos.","risk":"A carta escolhida será removida definitivamente do baralho.","cost":"Escolher uma carta para deixar a expedição.","action":"Aceitar a despedida"},"en":{"title":"Farewell Contract","story":"At a fork in the road, a companion receives an offer to escort merchants along another route. The parting will be friendly, and the merchants offer compensation so your expedition can continue.","opportunity":"Receive 20 gold, guaranteed.","risk":"The chosen card is permanently removed from your deck.","cost":"Choose one card to leave the expedition.","action":"Accept the farewell"}},"tesouro":{"pt-BR":{"title":"Tesouro vigiado","story":"Uma relíquia repousa entre dois guardiões imóveis. Talvez seus encantamentos tenham se apagado há séculos; talvez estejam apenas esperando que alguém toque no pedestal.","opportunity":"60% de receber uma relíquia imediatamente.","risk":"40% de iniciar um combate comum. A vitória concede a relíquia; a derrota encerra a run.","cost":"","action":"Tocar no pedestal"},"en":{"title":"Guarded Treasure","story":"A relic rests between two motionless guardians. Perhaps their enchantments faded centuries ago. Perhaps they are simply waiting for someone to touch the pedestal.","opportunity":"60% chance to receive a relic immediately.","risk":"40% chance to start a normal battle. Win to receive the relic; defeat ends the run.","cost":"","action":"Touch the pedestal"}},"profanado":{"pt-BR":{"title":"Santuário profanado","story":"Três relíquias pairam sobre um altar rachado, cercadas por fios de névoa violeta. Romper o selo pode libertar seus tesouros — ou despertar os protetores que a corrupção tornou ainda mais fortes.","opportunity":"50% de escolher uma entre três relíquias imediatamente.","risk":"50% de iniciar um combate com um terço dos personagens inimigos com +5% nos atributos. Vencendo, escolha entre as mesmas três relíquias; perder encerra a run.","cost":"","action":"Romper o selo"},"en":{"title":"Desecrated Sanctuary","story":"Three relics float above a cracked altar, surrounded by violet mist. Breaking the seal may release its treasures, or awaken protectors strengthened by corruption.","opportunity":"50% chance to immediately choose one of three relics.","risk":"50% chance to fight enemies with +5% stats on one third of their characters. Win to choose from the same three relics; defeat ends the run.","cost":"","action":"Break the seal"}},"ataque":{"pt-BR":{"title":"Caravana sob ataque","story":"Uma carroça bloqueia a ponte enquanto saqueadores cercam os viajantes. Alguns já procuram uma rota de fuga, mas, se o grupo oferecer ajuda, um deles promete seguir com vocês quando tudo terminar.","opportunity":"40% de escolher um recruta imediatamente.","risk":"60% de iniciar um combate. A vitória concede a escolha do recruta e mais 10 de ouro; a derrota encerra a run.","cost":"","action":"Ajudar a caravana"},"en":{"title":"Caravan Under Attack","story":"A wagon blocks the bridge while raiders surround the travelers. Some are already searching for an escape route. If your party helps, one traveler promises to join you once the danger passes.","opportunity":"40% chance to immediately choose a recruit.","risk":"60% chance to start a battle. Victory grants the recruit choice and 10 gold; defeat ends the run.","cost":"","action":"Help the caravan"}},"camara":{"pt-BR":{"title":"Câmara do campeão","story":"No fim de um salão monumental, um campeão guarda uma relíquia e um cofre dourado. Às vezes ele reconhece o valor dos visitantes e permite sua passagem; hoje, sua mão ainda repousa sobre a arma.","opportunity":"30% de receber uma relíquia e 20 de ouro imediatamente.","risk":"70% de enfrentar um elite com +5% nos atributos em um terço dos personagens e suas relíquias sorteadas. Vencer concede a relíquia e os 20 de ouro; perder encerra a run.","cost":"","action":"Entrar na câmara"},"en":{"title":"Champion's Chamber","story":"At the far end of a monumental hall, a champion guards a relic and a golden chest. Sometimes the champion recognizes a visitor's worth and lets them pass. Today, their hand still rests upon their weapon.","opportunity":"30% chance to immediately receive a relic and 20 gold.","risk":"70% chance to face an elite with +5% stats on one third of its characters and its rolled relics. Victory grants the relic and 20 gold; defeat ends the run.","cost":"","action":"Enter the chamber"}}};
